    """Tuned Best Fit (lo=4, hi=10, penalty=94): the tightest bin wins, but leaving a gap
    strictly between 4 and 10 units costs 94. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 94 * ((r > 4) & (r < 10))

