    """Tuned Best Fit (lo=3, hi=37, penalty=26): the tightest bin wins, but leaving a gap
    strictly between 3 and 37 units costs 26. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 26 * ((r > 3) & (r < 37))

